from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class FixedPointReport:
    dimension: float
    epsilon: float
    gaussian: float
    interacting: float
    gaussian_residual: float
    interacting_residual: float
    slope: float

def beta(epsilon: float, coupling: float) -> float:
    return -epsilon * coupling + 3.0 * coupling**2

def classify(dimension: float) -> FixedPointReport:
    epsilon = 4.0 - dimension
    interacting = epsilon / 3.0
    return FixedPointReport(dimension, epsilon, 0.0, interacting,
        beta(epsilon, 0.0), beta(epsilon, interacting),
        -epsilon + 6.0 * interacting)

if __name__ == "__main__":
    for d in (3.9, 3.5, 3.0, 4.0, 5.0):
        print(classify(d))

from __future__ import annotations

def eta_from_coupling(coupling: float) -> float:
    return coupling**2 / 6.0

def compare(epsilon: float) -> tuple[float, float, float]:
    coupling = epsilon / 3.0
    composed = eta_from_coupling(coupling)
    direct = epsilon**2 / 54.0
    return composed, direct, abs(composed - direct)

if __name__ == "__main__":
    print("epsilon  eta(g_*)       epsilon^2/54   discrepancy")
    for epsilon in (0.01, 0.1, 0.5, 1.0, -1.0):
        a, b, error = compare(epsilon)
        print(f"{epsilon:7.2f}  {a:13.9g}  {b:13.9g}  {error:.3e}")

from __future__ import annotations
from typing import Callable, Iterable

def audit(remainder: Callable[[float], float], constant: float, delta: float,
          samples: Iterable[float]) -> list[tuple[float, float, float, bool]]:
    if constant <= 0 or delta <= 0:
        raise ValueError("constant and delta must be positive")
    result = []
    for epsilon in samples:
        if abs(epsilon) >= delta:
            raise ValueError("sample outside the open neighborhood")
        lhs = abs(remainder(epsilon))
        rhs = constant * abs(epsilon)**3
        result.append((epsilon, lhs, rhs, lhs <= rhs + 1e-15))
    return result

if __name__ == "__main__":
    r = lambda epsilon: 0.2 * epsilon**3
    for row in audit(r, 0.2, 1.0, (-0.5, -0.1, 0.0, 0.1, 0.5)):
        print(row)

